const summarizeRetailSaleVatRates = `-- name: SummarizeRetailSaleVatRates :many
SELECT v.tax_rate, COALESCE(sum(v.tax_base), 0)::numeric AS tax_base, COALESCE(sum(v.tax_amount), 0)::numeric AS tax_amount
FROM retail_sale_vat_lines v
JOIN retail_sales s ON s.taxpayer_id = v.taxpayer_id AND s.id = v.retail_sale_id
WHERE v.taxpayer_id = $1
  AND ($2::text IS NULL OR s.period = $2::text)
  AND ($3::text IS NULL OR s.approval_status = $3::text)
  AND ($4::text IS NULL OR s.okc_serial_number = $4::text
       OR ($4::text = '-' AND s.okc_serial_number IS NULL))
GROUP BY v.tax_rate
ORDER BY v.tax_rate
`

type SummarizeRetailSaleVatRatesParams struct {
	TaxpayerID int64       `json:"taxpayer_id"`
	Period     pgtype.Text `json:"period"`
	Status     pgtype.Text `json:"status"`
	Okc        pgtype.Text `json:"okc"`
}

type SummarizeRetailSaleVatRatesRow struct {
	TaxRate   pgtype.Numeric `json:"tax_rate"`
	TaxBase   pgtype.Numeric `json:"tax_base"`
	TaxAmount pgtype.Numeric `json:"tax_amount"`
}

// Filtredeki Z raporlarının KDV oranı kırılımı.
func (q *Queries) SummarizeRetailSaleVatRates(ctx context.Context, arg SummarizeRetailSaleVatRatesParams) ([]SummarizeRetailSaleVatRatesRow, error) {
	rows, err := q.db.Query(ctx, summarizeRetailSaleVatRates,
		arg.TaxpayerID,
		arg.Period,
		arg.Status,
		arg.Okc,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeRetailSaleVatRatesRow{}
	for rows.Next() {
		var i SummarizeRetailSaleVatRatesRow
		if err := rows.Scan(&i.TaxRate, &i.TaxBase, &i.TaxAmount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
